head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > allowChar]<br/>AutoComplete 컴포넌트에 입력이 가능한 문자의 집합을 정규식의 문자클래스 형식으로 설정합니다.",
    "validation" : [
        "validate(), validateObject() 메소드로 유효성 체크 실행 시 mandatory 속성에 이어 유효성 체크가 실행됩니다.",
        "validate(), validateObject() 메소드로 유효성 체크 실행 시 getValue() 메소드의 반환값에 allowChar 속성에 설정되지 않은 문자가 포함되면 유효성 체크는 실패로 처리됩니다.",
        "validateObject() 메소드는 유효성 체크 항목(type)으로 'allowChar' 값을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 아이템 DataList 생성 : Value 는 허용 문자만(100) / 허용·비허용 혼합(B200) / 비허용 문자만(ICN)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_city">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_city.setJSON([
        { "label" : "Seoul", "value" : "100" },
        { "label" : "Busan", "value" : "B200" },
        { "label" : "Incheon", "value" : "ICN" }
    ]);

    // con 기본값 : allowChar=0-9, mandatory=true
    con_allowChar.setValue("0-9");
    con_mandatory.setValue("2");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- chooseOption=true 고정 (-선택- 아이템 Value 는 빈값, 생성 직후 선택됨)\n- 아이템 Value : Seoul=100, Busan=B200, Incheon=ICN\n[절차] 목록에서 아이템 선택 -> validate / validateObject"', '', 'label1');

    let properties = {
        allowChar : con_allowChar.getValue(),
        mandatory : con_mandatory.getText(),
        chooseOption : "true",
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// validate() 결과 출력 (validation 1, 2)
scwin.btn_validate_onclick = function (e) {
    let value = target1.getValue();
    let rtn = target1.validate();
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : '" + value + "' -> validate() : " + rtn);
};



// validateObject() 결과 출력 (validation 1, 2, 3)
scwin.btn_validateObject_onclick = function (e) {
    let value = target1.getValue();
    let rtnObj = target1.validateObject();
    let strObj = "{}";
    if (rtnObj && typeof rtnObj.type !== "undefined") {
        strObj = "{ callerId : " + rtnObj.callerId + ", type : " + rtnObj.type + ", value : " + rtnObj.value + " }";
    }
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : '" + value + "' -> validateObject() : " + strObj);
};
